From 8ec13341f2f9378eb8059d2077126aad1e95b1f7 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 12:55:16 +0100
Subject: [PATCH] applets/clipboard: add an action to export the history to a
 text file
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

Since the history moved to an SQLite database there was no easy way to
get all of it out at once. Add an "Export History…" action to the menu
of the applet that saves every text and URL entry to a chosen file.

BUG: 307792
---
 applets/clipboard/qml/main.qml                | 19 ++++++++++++++++++
 .../declarative/declarativehistorymodel.cpp   | 20 +++++++++++++++++++
 klipper/declarative/declarativehistorymodel.h |  3 +++
 3 files changed, 42 insertions(+)

diff --git a/applets/clipboard/qml/main.qml b/applets/clipboard/qml/main.qml
index 101b18486a..f704e3e400 100644
--- a/applets/clipboard/qml/main.qml
+++ b/applets/clipboard/qml/main.qml
@@ -10,6 +10,7 @@ pragma ComponentBehavior: Bound
 import QtQuick
 import QtQuick.Layouts
 import QtQuick.Controls as QQC2 // For StackView
+import QtQuick.Dialogs as QtDialogs
 import QtQuick.Templates as T
 import org.kde.plasma.plasmoid
 import org.kde.plasma.core as PlasmaCore
@@ -88,6 +89,13 @@ PlasmoidItem {
             visible: !main.isClipboardEmpty
             onTriggered: main.clipboardMenu.clearHistory()
         },
+        PlasmaCore.Action {
+            text: i18nc("@action:inmenu", "Export History…")
+            icon.name: "document-export"
+            priority: PlasmaCore.Action.LowPriority
+            visible: !main.isClipboardEmpty
+            onTriggered: exportDialog.open()
+        },
         PlasmaCore.Action {
             id: copyClipboardAction

@@ -120,6 +128,17 @@ PlasmoidItem {
         id: historyModel
     }

+    QtDialogs.FileDialog {
+        id: exportDialog
+        title: i18nc("@title:window", "Export Clipboard History")
+        fileMode: QtDialogs.FileDialog.SaveFile
+        defaultSuffix: "txt"
+        nameFilters: [i18n("Text files (*.txt)"), i18n("All files (*)")]
+        onAccepted: if (!historyModel.exportToFile(selectedFile)) {
+            console.warn("Could not export the clipboard history to", selectedFile);
+        }
+    }
+
     fullRepresentation: PlasmaExtras.Representation {
         id: dialogItem
         Layout.minimumWidth: Kirigami.Units.gridUnit * 24
diff --git a/klipper/declarative/declarativehistorymodel.cpp b/klipper/declarative/declarativehistorymodel.cpp
index 9c44a5188b..0899f05343 100644
--- a/klipper/declarative/declarativehistorymodel.cpp
+++ b/klipper/declarative/declarativehistorymodel.cpp
@@ -9,6 +9,8 @@
 #include "historymodel.h"
 #include "klipper.h"

+#include <QSaveFile>
+
 DeclarativeHistoryModel::DeclarativeHistoryModel(QObject *parent)
     : QSortFilterProxyModel(parent)
     , m_model(HistoryModel::self())
@@ -98,6 +100,24 @@ void DeclarativeHistoryModel::invokeAction(const QString &uuid)
     }
 }

+bool DeclarativeHistoryModel::exportToFile(const QUrl &url) const
+{
+    QStringList texts;
+    for (const auto &item : std::as_const(m_model->m_items)) {
+        if (item->type() != HistoryItemType::Image && !item->text().isEmpty()) {
+            texts.append(item->text());
+        }
+    }
+
+    QSaveFile file(url.toLocalFile());
+    if (!file.open(QIODevice::WriteOnly | QIODevice::Text)) {
+        return false;
+    }
+    file.write(texts.join(QLatin1Char('\n')).toUtf8());
+    file.write("\n");
+    return file.commit();
+}
+
 bool DeclarativeHistoryModel::filterAcceptsRow(int sourceRow, const QModelIndex &sourceParent) const
 {
     if (m_starredOnly) {
diff --git a/klipper/declarative/declarativehistorymodel.h b/klipper/declarative/declarativehistorymodel.h
index bd239fbbc8..b5459d445f 100644
--- a/klipper/declarative/declarativehistorymodel.h
+++ b/klipper/declarative/declarativehistorymodel.h
@@ -8,6 +8,7 @@

 #include <QPropertyNotifier>
 #include <QSortFilterProxyModel>
+#include <QUrl>
 #include <qqmlregistration.h>

 class HistoryModel;
@@ -46,6 +47,8 @@ public:

     Q_INVOKABLE void invokeAction(const QString &uuid);

+    Q_INVOKABLE bool exportToFile(const QUrl &url) const;
+
 Q_SIGNALS:
     void countChanged();
     void sourceCountChanged();
